# Hypothesis: guess-attending heads' queries align with a low-frequency 'guess key' direction; quantify per head
def keys(l, h_res):  # h_res: (...,640) recorded residual input to layer l
    win=W(f'model.layers.{l}.input_layernorm.weight'); Wk=W(f'model.layers.{l}.self_attn.k_proj.weight'); kn=W(f'model.layers.{l}.self_attn.k_norm.weight')
    k=(rmsn(h_res)*(1+win))@Wk.T; return rmsn(k)*(1+kn)
def queries(l, h, h_res):
    win=W(f'model.layers.{l}.input_layernorm.weight'); Wq=W(f'model.layers.{l}.self_attn.q_proj.weight')[h*256:(h+1)*256]; qn=W(f'model.layers.{l}.self_attn.q_norm.weight')
    q=(rmsn(h_res)*(1+win))@Wq.T; return rmsn(q)*(1+qn)
def lowmask(l):
    th=1e6 if cfg['layer_types'][l]=='full_attention' else 1e4
    i=np.arange(128); inv=th**(-2*i/256); m=(40*inv<0.5); return np.concatenate([m,m])
